def maxRunTime(n: int, batteries: list[int]) -> int:
    lo, hi = 1, sum(batteries) // n
    ans = 0
    while lo <= hi:
        target = (lo + hi) // 2
        total = sum(min(b, target) for b in batteries)
        if total >= target * n:
            ans = target
            lo = target + 1
        else:
            hi = target - 1
    return ans

